def backfill_exeat_active_state(apps, schema_editor):
    """Mark existing Approved passes that have no recorded return as active.

    If historical data already contains more than one active pass for a
    student, stop with a clear report instead of silently choosing one. Staff
    must resolve the conflict before the unique constraint can be applied.
    """
