    ExeatReconciliation = apps.get_model("core", "ExeatReconciliation")

    for exeat in Exeat.objects.filter(status="Approved").iterator():
        movement = (
            ExeatMovement.objects.filter(exeat_id=exeat.pk)
            .only("actual_return")
            .first()
        )
        reconciliation = (
            ExeatReconciliation.objects.filter(exeat_id=exeat.pk)
            .only("outcome", "actual_return")
            .first()
        )
        if reconciliation is not None:
            is_active = (
                reconciliation.outcome == "student_out"
                and reconciliation.actual_return is None
            )
        elif movement is not None:
            is_active = movement.actual_return is None
        else:
            is_active = True

        if is_active:
            Exeat.objects.filter(pk=exeat.pk).update(is_active=True)

